245	/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
246	pub(crate) fn version_is_tagged(
247	    tags: &crate::TagIndex,
248	    package: &callisto_model::PackageId,
249	    version: &Version,
250	) -> bool {
251	    tags.contains_tag(&tags.template(package).render(version).to_string())
252	        || tags.last_tag(package).is_some_and(|tag| &tag.version == version)
253	}
