83	/// Derives the intent for every unreleased package (or exactly `selections`).
84	///
85	/// This is the one plan derivation behind both `callisto release --dry-run`
86	/// and `callisto release`; `None` means nothing is unreleased.
87	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
88	    root: &Path,
89	    locator: &L,
90	    runner: &R,
91	    selections: &[ReleasePackageId],
92	    mode: LocalReleaseSource,
93	) -> Result<Option<LocalReleasePlan>, GraphError> {
94	    let root = canonical_root(root)?;
95	    let workspace = Workspace::load(root, locator, runner)?;
96	    plan_workspace_release(&workspace, selections, mode)
