99	/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
100	pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
101	    workspace: &Workspace<'_, R, D>,
102	    selections: &[ReleasePackageId],
103	    mode: LocalReleaseSource,
104	) -> Result<Option<LocalReleasePlan>, GraphError> {
105	    let Some(decision) = crate::commands::derive_unreleased_decision(workspace, selections)? else {
106	        return Ok(None);
107	    };
108	    let profile = ExecutionTrustProfileV1::GitCommit;
109	    let source = match mode {
110	        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
111	            sha: workspace.git_access().head_sha()?,
112	        },
113	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
114	    };
115	    // A local run is its own orchestration: slots bind to the source commit.
116	    let artifact_policy = match (&workspace.config.product_release, &source) {
117	        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
118	            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
119	                repository,
120	                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
121	                workflow_commit: sha.clone(),
122	            })
123	        }
124	        _ => None,
125	    };
126	    let remote = match mode {
127	        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
128	        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
129	    };
130	    let mut diagnostics = Vec::new();
131	    let intent = derive_release_intent(
132	        workspace,
133	        &decision,
134	        source.clone(),
135	        profile,
136	        artifact_policy.as_ref(),
137	        remote,
138	        &mut diagnostics,
139	    )?;
140	    let tags_unbound = mode == LocalReleaseSource::Preview
141	        && intent
142	            .operations
143	            .iter()
144	            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
145	        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
146	    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
147	        return Err(GraphError::ReleaseIntentStale {
148	            reason: StaleReason::source_identity_changed(),
149	        });
150	    }
151	    Ok(Some(LocalReleasePlan {
152	        intent,
153	        tags_unbound,
154	        diagnostics,
155	    }))
156	}
