428	/// Writes `to` unless the manifest already has it, and refuses any version other than `from`:
429	/// the precondition that makes re-running an interrupted apply safe. Returns whether it wrote.
430	fn write_version_guarded(
431	    handle: &mut dyn Manifest,
432	    path: &Path,
433	    from: &Version,
434	    to: &Version,
435	    permit: &ApplyPermit,
436	) -> Result<bool, GraphError> {
437	    let current = handle.current_version()?;
438	    if current == *to {
439	        return Ok(false);
440	    }
441	    if current != *from {
442	        return Err(GraphError::UnexpectedManifestVersion {
443	            path: path.to_path_buf(),
444	            expected_from: from.clone(),
445	            expected_to: to.clone(),
446	            found: current,
447	        });
448	    }
449	    handle.write_version(to, permit)?;
450	    Ok(true)
451	}
