1055	/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
1056	///
1057	/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
1058	/// string (`ActionManifestManagerWrapper.ParseActionReference` in
1059	/// `actions/runner`), so a ref that itself contains `@` -- like the
1060	/// `callisto@<version>` tag this project releases under -- can never be
1061	/// written directly as `owner/repo/path@callisto@<version>`: the split lands
1062	/// inside the ref, not before it, and resolution fails. The generated
1063	/// workflow pins to this tag's resolved commit instead, like every other
1064	/// external action reference in this repository.
1065	///
1066	/// # Errors
1067	///
1068	/// The remote is unreachable, or `callisto@<version>` is not a published tag.
1069	pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
1070	    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
1071	    let reference = format!("refs/tags/callisto@{version}");
1072	    // The peeled ref resolves an annotated tag to its commit; a lightweight
1073	    // tag has no peeled line, and its own SHA already is the commit.
1074	    let peeled = format!("{reference}^{{}}");
1075	    // A transport-level failure (git not found, timed out, ...) keeps its
1076	    // real cause via `GraphError::Command`; only a clean run that still
1077	    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
1078	    let output = runner.run_quiet(
1079	        programs::GIT,
1080	        &["ls-remote", ENDPOINT, &reference, &peeled],
1081	        root,
1082	        timeouts::GIT_LS_REMOTE,
1083	    )?;
1084	    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
1085	        version: version.to_owned(),
1086	    };
1087	    if output.exit_code != Some(0) {
1088	        return Err(unresolved());
1089	    }
1090	    let mut tag_object = None;
1091	    let mut commit = None;
1092	    for line in output.stdout.lines() {
1093	        let Some((sha, found)) = line.split_once('\t') else {
1094	            continue;
1095	        };
1096	        match found.trim() {
1097	            found if found == peeled => commit = Some(sha.trim().to_owned()),
1098	            found if found == reference => tag_object = Some(sha.trim().to_owned()),
1099	            _ => {}
1100	        }
1101	    }
1102	    commit.or(tag_object).ok_or_else(unresolved)
1103	}
